const must = (l, i) => { const L = J(`campMissionRow(${l}, ${i})`), out = []; const sc = (L.objectives.find(o => o.type === 'scan') || {}).points; if (sc) out.push(sc.length, sc[0].secs); const dv = L.objectives.find(o => o.type === 'deliver'); if (dv) out.push(L.convoys.length, dv.n); if (dv && L.convoys.length > 1) out.push(L.convoys[1].at - L.convoys[0].at); const ca = L.objectives.find(o => o.type === 'caches'); if (ca) out.push(ca.n, L.caches.length); if (L.guards) out.push(L.guards.length); if (L.relic) out.push(L.relic.hold); (L.towers || []).forEach(t => out.push(t.n)); return out; };
